function owT(k){return OW_WORDS[k]?.[{ru:0,en:1,it:2}[state.lang]??1]||k}
function owId(p){return p+'-'+crypto.randomUUID()}
function owRound(n){return Math.round((n+Number.EPSILON)*100)/100}
function owClient(id=state.orderDesk.activeClientId){return state.orderDesk.clients.find(c=>c.id===id)}
function owInit(){
 if(state.orderDesk?.version===2)return;
 const clients=[{id:'c-milano',kind:'company',name:'Concept Store Milano',contactName:'Luca Demo',city:'Milano',country:'Italy',email:'buyer@example.com',phone:'',discount:8,prices:{},terms:'FW 26/27 · demo wholesale',paymentTerms:'30% deposit · Demo',deliveryDate:'',active:true},{id:'c-paris',kind:'company',name:'Atelier Paris',contactName:'Camille Demo',city:'Paris',country:'France',email:'paris@example.com',phone:'',discount:5,prices:{p1:{price:250}},terms:'Demo wholesale account',paymentTerms:'Net 30 · Demo',active:true},{id:'c-private',kind:'person',name:'Andrea Rossi',contactName:'Andrea Rossi',city:'Roma',country:'Italy',email:'private@example.com',phone:'',discount:0,prices:{},terms:'Private client · Demo',paymentTerms:'On confirmation · Demo',active:true},{id:'c-luce',kind:'company',name:'Luce Milano · Buyer',contactName:'Buyer Demo',city:'Milano',country:'Italy',email:'luce@example.com',phone:'',discount:0,prices:{},terms:'Demo wholesale account',paymentTerms:'To agree · Demo',active:true}];
 state.orderDesk={version:2,clients,activeClientId:'c-milano',wishlists:{'c-milano':(state.favorites||[]).slice()},drafts:{},carts:{},activity:(state.intent||[]).map(x=>({...x,clientId:'c-milano',source:'legacy-demo'})),requests:[],sets:[{id:'set-demo-01',name:'Napoli · Tailored Pair',productIds:['p1','p4'],description:'',active:true}],filters:{season:'All',clientId:'All',country:'All',city:'All',kind:'All',status:'All',group:'articles'},adminTab:'dashboard'};
 for(const p of state.products){p.photos=p.photos||[p.image].filter(Boolean);p.localPhotos=p.localPhotos||[];p.videoUrl=p.videoUrl||'';p.composition=p.composition||p.fabric;p.care=p.care||'';p.fit=p.fit||'';p.origin=p.origin||'';p.details=p.details||'';p.season=p.season||p.collection;p.deliveryDate=p.deliveryDate||''}
 for(const o of state.orders){o.clientId=clients.find(c=>c.name===o.client)?.id||(o.type==='wholesale'?'c-milano':'c-private');o.clientSnapshot=o.clientSnapshot||structuredClone(owClient(o.clientId));o.revision=o.revision||1;o.discount=o.discount||0;o.terms=o.terms||owClient(o.clientId).terms;o.paymentTerms=o.paymentTerms||owClient(o.clientId).paymentTerms;o.audit=o.audit||[];o.revisions=o.revisions||[];o.lines=o.lines.map(l=>owSnapshot(l));o.status=['confirmed','completed','shipped','inProduction'].includes(o.status)?'confirmed':['draft','cancelled'].includes(o.status)?o.status:'submitted';if(o.status==='confirmed'){o.brandAcceptedAt=o.brandAcceptedAt||o.updated;o.clientAcceptedAt=o.clientAcceptedAt||o.updated}}
 delete state.salesOS;delete state.sellThrough;delete state.retailHistory;delete state.pendingProposalId;state.customDraft=[];state.adminTab='dashboard';
 owActivate('c-milano',false);save();
}
function owSnapshot(l){const p=state.products.find(x=>x.id===l.productId);return{...l,article:l.article||p?.article||'',name:l.name||p?.name||l.productId,season:l.season||p?.season||p?.collection||'',composition:l.composition||p?.composition||p?.fabric||'',deliveryDate:l.deliveryDate||p?.deliveryDate||state.collections.find(c=>c.name===p?.collection)?.deliveryDate||'',unit:owRound(Number(l.unit)||0)}}
function owActivate(id,persist=true){
 const c=owClient(id);if(!c||!c.active)return false;
 const d=state.orderDesk;if(persist){d.drafts[d.activeClientId]={draft:structuredClone(state.draft),draftMeta:structuredClone(state.draftMeta),customDraft:structuredClone(state.customDraft||[]),draftOrderId:state.draftOrderId};d.carts[d.activeClientId]=structuredClone(state.cart)}
 d.activeClientId=id;const saved=d.drafts[id]||{};state.draft=saved.draft||{};state.draftMeta=saved.draftMeta||{client:c.name,delivery:c.deliveryDate||'',notes:''};state.customDraft=saved.customDraft||[];state.cart=d.carts[id]||[];state.draftOrderId=saved.draftOrderId;
 state.favorites=d.wishlists[id]||[];state.buyerProfile={name:c.name,market:[c.city,c.country].filter(Boolean).join(' · '),terms:c.paymentTerms,priceList:c.kind==='company'?'Wholesale · EUR':'Private · EUR',discount:c.discount,assortment:'FW 26/27'};if(state.role!=='brand')state.role=c.kind==='company'?'buyer':'private';
 if(persist){save();renderAll()}return true;
}
function owPrice(p,clientId=state.orderDesk.activeClientId){const c=owClient(clientId),rule=c?.prices?.[p.id],base=c?.kind==='person'?Number(p.b2c):Number(p.b2b);if(rule?.price!=null)return owRound(rule.price);return owRound(base*(1-(rule?.discount??c?.discount??0)/100))}
function owClientSelect(scope){return `<label class="ow-label" for="owClient-${scope}">${owT('selectClient')}</label><select id="owClient-${scope}" class="field" onchange="owActivate(this.value)">${state.orderDesk.clients.filter(c=>c.active).map(c=>`<option value="${c.id}" ${c.id===state.orderDesk.activeClientId?'selected':''}>${esc(c.name)} · ${owT(c.kind==='company'?'company':'person')}</option>`).join('')}</select>`}
function owLog(type,productId='',value=0){const d=state.orderDesk;d.activity.unshift({id:owId('EV'),type,productId,value,clientId:d.activeClientId,clientSnapshot:structuredClone(owClient()),at:new Date().toISOString(),source:'local-demo'});d.activity=d.activity.slice(0,5000);state.intent=d.activity;save()}
function owWishlist(pid,e){e?.stopPropagation();const p=state.products.find(x=>x.id===pid);if(!p?.active)return;const d=state.orderDesk,id=d.activeClientId,list=d.wishlists[id]||[];const i=list.indexOf(pid);if(i>=0)list.splice(i,1);else list.push(pid);d.wishlists[id]=list;state.favorites=list;owLog(i>=0?'unsave':'save',pid);renderHeader();renderCollection();if(state.page==='portal')renderPortal();if(state.page==='quick')renderQuick()}
function owValidateLine(l){const p=state.products.find(x=>x.id===l.productId);if(!p?.active||!Number.isSafeInteger(l.qty)||l.qty<=0||!Number.isFinite(l.unit)||l.unit<0)return false;if(l.requestId){const r=state.orderDesk.requests.find(x=>x.id===l.requestId);return r?.status==='accepted'&&r.clientId===state.orderDesk.activeClientId&&r.productId===l.productId&&r.qty===l.qty&&r.unit===l.unit&&!r.orderId}return p.sizes.includes(l.size)&&p.colors.some(c=>c[0]===l.color)}
function owDraftLines(){const ls=[];for(const [pid,cs] of Object.entries(state.draft)){const p=state.products.find(x=>x.id===pid);if(!p)continue;for(const [color,ss] of Object.entries(cs))for(const [size,q] of Object.entries(ss))if(Number(q)>0)ls.push(owSnapshot({productId:pid,color,size,qty:Number(q),unit:owPrice(p)}))}for(const r of state.customDraft||[])ls.push(owSnapshot(r));return ls}
function owMakeOrder(status){
 const ls=owDraftLines();if(!ls.length||ls.some(l=>!owValidateLine(l))){toast(ls.length?owT('blocked'):t('emptyOrder'),true);return null}
 const c=owClient(),old=state.orders.find(o=>o.id===state.draftOrderId&&o.clientId===c.id&&o.status==='draft');const at=new Date().toISOString();
 const o={id:old?.id||owId('MP'),clientId:c.id,type:c.kind==='company'?'wholesale':'b2c',client:c.name,clientSnapshot:structuredClone(c),contact:c.email,status,manager:old?.manager||'Brand Team',delivery:state.draftMeta.delivery||c.deliveryDate||'',notes:state.draftMeta.notes||'',created:old?.created||at,updated:at,revision:1,discount:0,terms:c.terms,paymentTerms:c.paymentTerms,lines:ls,messages:old?.messages||[],internal:old?.internal||[],audit:old?.audit||[],revisions:old?.revisions||[],unread:false};
 o.audit.push({at,action:status,actor:c.contactName||c.name,clientId:c.id});if(old)state.orders[state.orders.indexOf(old)]=o;else state.orders.unshift(o);state.selectedOrder=o.id;owLog(status,'',orderValue(o));
 if(status==='draft')state.draftOrderId=o.id;else{for(const l of ls.filter(l=>l.requestId)){const r=state.orderDesk.requests.find(r=>r.id===l.requestId);if(r)r.orderId=o.id}state.draft={};state.customDraft=[];delete state.draftOrderId;state.draftMeta={client:c.name,delivery:'',notes:''}}save();return o;
}
function owSubmit(){if(owMakeOrder('submitted')){toast(t('orderSubmitted'));go('orders')}}
function owSaveDraft(){if(owMakeOrder('draft')){toast(t('draftSaved'));renderSummary()}}
function owVisibleOrders(){return state.orders.filter(o=>state.role==='brand'||o.clientId===state.orderDesk.activeClientId)}
function owConfirmed(o){return o.status==='confirmed'&&!!o.brandAcceptedAt&&!!o.clientAcceptedAt}
function owRevise(o,reason){if(!reason?.trim())throw Error(owT('reason'));o.revisions.push({revision:o.revision,status:o.status,lines:structuredClone(o.lines),discount:o.discount,delivery:o.delivery,terms:o.terms,paymentTerms:o.paymentTerms,at:new Date().toISOString(),brandAcceptedAt:o.brandAcceptedAt,clientAcceptedAt:o.clientAcceptedAt});o.revision++;o.status='inReview';delete o.brandAcceptedAt;delete o.clientAcceptedAt;o.audit.push({action:'revision',comment:reason,actor:'Brand Team',at:new Date().toISOString()})}
function owOffer(id){const o=state.orders.find(x=>x.id===id);if(state.role!=='brand'||!o||!['submitted','inReview'].includes(o.status)||!o.lines.length||o.lines.some(l=>!Number.isSafeInteger(l.qty)||l.qty<=0||!Number.isFinite(l.unit)||l.unit<0))return false;o.brandAcceptedAt=new Date().toISOString();o.status='offer';o.audit.push({action:'offer',actor:'Brand Team',at:o.brandAcceptedAt});o.messages.push({from:'brand',text:owT('offer')+' · '+owT('revision')+' '+o.revision,at:o.brandAcceptedAt});save();renderOrders();renderAdmin();return true}
function owAccept(id){const o=state.orders.find(x=>x.id===id);if(state.role==='brand'||o?.clientId!==state.orderDesk.activeClientId||o.status!=='offer'||!o.brandAcceptedAt)return false;o.clientAcceptedAt=new Date().toISOString();o.status='confirmed';o.updated=o.clientAcceptedAt;o.audit.push({action:'confirmed',actor:owClient().contactName||owClient().name,at:o.clientAcceptedAt});save();renderOrders();renderPortal();return true}
function owCancel(id){const o=state.orders.find(x=>x.id===id);if(!o||state.role!=='brand'||o.status==='cancelled')return false;owRevise(o,owT('cancelled'));o.status='cancelled';save();renderOrders();renderAdmin();return true}
function owStatus(s){return owT(['draft','submitted','inReview','offer','confirmed','cancelled'].includes(s)?s:'submitted')}
function owDelivery(p){const c=state.collections.find(c=>c.name===p.collection);const d=p.deliveryDate||c?.deliveryDate;return d?d+(p.deliveryEnd||c?.deliveryEnd?' — '+(p.deliveryEnd||c.deliveryEnd):''):owT('dateUnknown')}
const OW_MEDIA=new Map();let owUploadSession={photos:[],videoId:''};let owUploading=0;
function owDB(){return new Promise((resolve,reject)=>{const q=indexedDB.open('mpOrderWorkspaceMedia',1);q.onupgradeneeded=()=>q.result.createObjectStore('media',{keyPath:'id'});q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)})}
async function owMediaPut(file){const db=await owDB(),id=owId('MEDIA');await new Promise((resolve,reject)=>{const tx=db.transaction('media','readwrite');tx.objectStore('media').put({id,blob:file,name:file.name});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close();OW_MEDIA.set(id,URL.createObjectURL(file));return id}
async function owMediaLoad(){if(typeof indexedDB==='undefined')return;const db=await owDB();const rows=await new Promise((resolve,reject)=>{const q=db.transaction('media').objectStore('media').getAll();q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)});db.close();for(const r of rows)OW_MEDIA.set(r.id,URL.createObjectURL(r.blob));renderCollection();if(state.page==='admin')renderAdmin()}
function owURL(u){if(!u)return '';if(/[<>"'\\]/.test(u))throw Error('URL');const url=new URL(u);if(url.protocol!=='https:')throw Error('HTTPS');return url.href}
function owCover(p){return (p.localPhotos||[]).map(id=>OW_MEDIA.get(id)).find(Boolean)||p.photos?.[0]||p.image||''}
function owMediaHtml(p){const imgs=[...(p.localPhotos||[]).map(id=>OW_MEDIA.get(id)).filter(Boolean),...(p.photos||[])];const video=OW_MEDIA.get(p.videoId)||p.videoUrl;return `<div class="ow-gallery">${imgs.length?imgs.map((u,i)=>`<img src="${esc(u)}" alt="${esc(p.name)} · ${i+1}" loading="lazy">`).join(''):'<div class="empty">'+owT('photos')+'</div>'}${video?`<video controls playsinline preload="metadata" src="${esc(video)}" aria-label="${esc(p.name)}"></video>`:''}</div>`}
async function owUpload(input,kind){const session=owUploadSession;owUploading++;try{const files=Array.from(input.files||[]);if(!files.length)return;if(kind==='photo'&&(files.length>8||files.some(f=>!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>8*1024*1024))||kind==='video'&&(files.length!==1||!['video/mp4','video/webm'].includes(files[0].type)||files[0].size>30*1024*1024))throw Error(owT('mediaHint'));if(kind==='photo'){const ids=[];for(const f of files)ids.push(await owMediaPut(f));session.photos=ids}else session.videoId=await owMediaPut(files[0]);if(session===owUploadSession&&document.getElementById('owMediaResult'))document.getElementById('owMediaResult').textContent=owT('saved')+' · '+files.length}catch(e){if(document.getElementById('owMediaResult'))document.getElementById('owMediaResult').textContent=owT('invalid')+' '+e.message}finally{owUploading--}}
function owField(id,label,value='',type='text',full=false){return `<div class="${full?'full':''}"><label class="label" for="${id}">${esc(label)}</label><div class="inputbox">${type==='textarea'?`<textarea id="${id}">${esc(value)}</textarea>`:`<input id="${id}" type="${type}" value="${esc(value)}">`}</div></div>`}
function owFormHead(title){return `<div class="modal-head"><div><div class="eyebrow">Marco Pescarolo · ${owT('admin')}</div><h2>${esc(title)}</h2></div><button class="x" onclick="closeOverlay()">×</button></div>`}
function owFormError(msg){const el=document.getElementById('owFormError');if(el)el.textContent=owT('invalid')+' '+msg;else toast(owT('invalid')+' '+msg,true)}
function owProductForm(id,duplicate=false){if(state.role!=='brand')return;const base=state.products.find(x=>x.id===id);const p=base?structuredClone(base):{id:'',name:'',article:'',gender:'MAN',category:'Trousers',collection:state.collections[0]?.name||'',season:'FW 26/27',sizes:['46','48','50','52','54'],colors:[['Stone','#b7aa98']],b2b:0,b2c:0,active:false,photos:[],localPhotos:[]};if(duplicate){p.id='';p.article='';p.name+=' Copy'}owUploadSession={photos:p.localPhotos||[],videoId:p.videoId||''};
 modal(owFormHead(p.name||owT('add'))+`<input id="opfId" type="hidden" value="${p.id}"><div class="form-grid">${owField('opfName',owT('name'),p.name)}${owField('opfArticle',t('article'),p.article)}${owField('opfSeason',owT('season'),p.season||p.collection)}<div><label class="label" for="opfCollection">${t('collection')}</label><div class="inputbox"><select id="opfCollection">${state.collections.map(c=>`<option ${c.name===p.collection?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div></div>${owField('opfCategory',owT('category'),p.category)}<div><label class="label" for="opfGender">${t('line')}</label><div class="inputbox"><select id="opfGender">${['MAN','LEI','BOTH'].map(g=>`<option ${g===p.gender?'selected':''}>${g}</option>`).join('')}</select></div></div>${owField('opfDescription',t('description'),p.description,'textarea',true)}${owField('opfComposition',owT('composition'),p.composition||p.fabric,'text',true)}${owField('opfFit',owT('fit'),p.fit)}${owField('opfCare',owT('care'),p.care)}${owField('opfOrigin',owT('origin'),p.origin)}${owField('opfLead',t('leadTime'),p.lead)}${owField('opfColors',owT('colors'),p.colors.map(c=>c.join(':')).join(', '),'text',true)}${owField('opfSizes',owT('sizes'),p.sizes.join(', '),'text',true)}${owField('opfB2B',t('b2bPrice'),p.b2b,'number')}${owField('opfB2C',t('b2cPrice'),p.b2c,'number')}${owField('opfDelivery',owT('delivery'),p.deliveryDate,'date')}${owField('opfDeliveryEnd',owT('deliveryEnd'),p.deliveryEnd,'date')}${owField('opfPhotos',owT('photos'),(p.photos||[]).join('\n'),'textarea',true)}${owField('opfVideo',owT('video'),p.videoUrl,'url',true)}<div class="full"><p class="micro">${owT('mediaHint')}</p><label class="ow-label" for="opfUpload">${owT('upload')}</label><input id="opfUpload" type="file" accept="image/jpeg,image/png,image/webp" multiple onchange="owUpload(this,'photo')"><label class="ow-label" for="opfUploadVideo">${owT('uploadVideo')}</label><input id="opfUploadVideo" type="file" accept="video/mp4,video/webm" onchange="owUpload(this,'video')"><p id="owMediaResult" class="micro">${owUploadSession.photos.length} ${owT('photos')}</p><button type="button" class="btn small secondary" onclick="owUploadSession={photos:[],videoId:''};document.getElementById('owMediaResult').textContent='0'">${owT('remove')}</button></div>${owField('opfDetails',owT('details'),p.details,'textarea',true)}<div><label class="label" for="opfActive">${owT('active')}</label><div class="inputbox"><select id="opfActive"><option value="false" ${p.active===false?'selected':''}>${owT('inactive')}</option><option value="true" ${p.active!==false?'selected':''}>${owT('active')}</option></select></div></div></div><p id="owFormError" role="alert" class="ow-error"></p><div class="modal-actions"><button class="btn secondary" onclick="closeOverlay()">${owT('cancel')}</button><button class="btn" onclick="owProductSaveUI()">${owT('save')}</button></div>`,'wide');
}
function owSaveProduct(p){if(state.role!=='brand')throw Error('Brand role required');if(!p.name.trim()||!p.article.trim()||!p.season.trim()||!p.collection.trim()||state.products.some(x=>x.article.toLowerCase()===p.article.toLowerCase()&&x.id!==p.id)||!p.sizes.length||!p.colors.length||new Set(p.sizes).size!==p.sizes.length||new Set(p.colors.map(c=>c[0])).size!==p.colors.length||p.colors.some(c=>!c[0]||!/^#[0-9a-f]{6}$/i.test(c[1]))||[p.b2b,p.b2c].some(n=>!Number.isFinite(n)||n<0)||p.deliveryDate&&p.deliveryEnd&&p.deliveryEnd<p.deliveryDate)throw Error('Name / unique article / variants / prices / delivery');p.photos=p.photos.map(owURL);p.videoUrl=owURL(p.videoUrl);p.image=p.photos[0]||'';p.fabric=p.composition;p.id=p.id||owId('P');p.updatedAt=new Date().toISOString();const i=state.products.findIndex(x=>x.id===p.id);if(i<0)state.products.push(p);else state.products[i]={...state.products[i],...p};save();return p.id}
function owProductSaveUI(){const v=id=>document.getElementById(id).value.trim();try{if(owUploading)throw Error('Upload in progress');owSaveProduct({id:v('opfId'),name:v('opfName'),article:v('opfArticle'),season:v('opfSeason'),collection:v('opfCollection'),category:v('opfCategory'),gender:v('opfGender'),description:v('opfDescription'),composition:v('opfComposition'),fit:v('opfFit'),care:v('opfCare'),origin:v('opfOrigin'),lead:v('opfLead'),colors:v('opfColors').split(',').map(x=>x.trim().split(':').map(y=>y.trim())),sizes:v('opfSizes').split(',').map(x=>x.trim()).filter(Boolean),b2b:Number(v('opfB2B')),b2c:Number(v('opfB2C')),deliveryDate:v('opfDelivery'),deliveryEnd:v('opfDeliveryEnd'),photos:v('opfPhotos').split(/\r?\n/).map(x=>x.trim()).filter(Boolean),localPhotos:owUploadSession.photos,videoUrl:v('opfVideo'),videoId:owUploadSession.videoId,details:v('opfDetails'),active:v('opfActive')==='true',tag:'new',availability:'available'});closeOverlay();renderAll();toast(owT('saved'))}catch(e){owFormError(e.message)}}
function owToggleProduct(id){if(state.role!=='brand')return;const p=state.products.find(x=>x.id===id);p.active=!p.active;p.updatedAt=new Date().toISOString();save();renderAll()}
function owClientForm(id){if(state.role!=='brand')return;const c=structuredClone((id?owClient(id):null)||{id:'',kind:'company',name:'',contactName:'',city:'',country:'',email:'',phone:'',discount:0,prices:{},terms:'',paymentTerms:'',deliveryDate:'',active:true});modal(owFormHead(c.name||owT('add'))+`<input id="ocId" type="hidden" value="${c.id}"><div class="form-grid"><div><label class="label" for="ocKind">${owT('client')}</label><div class="inputbox"><select id="ocKind"><option value="company" ${c.kind==='company'?'selected':''}>${owT('company')}</option><option value="person" ${c.kind==='person'?'selected':''}>${owT('person')}</option></select></div></div>${owField('ocName',owT('name'),c.name)}${owField('ocLegal',owT('legalName'),c.legalName||'')}${owField('ocContact',owT('contact'),c.contactName)}${owField('ocEmail',owT('email'),c.email,'email')}${owField('ocPhone',owT('phone'),c.phone)}${owField('ocCity',owT('city'),c.city)}${owField('ocCountry',owT('country'),c.country)}${owField('ocDiscount',owT('discount'),c.discount,'number')}${owField('ocDelivery',owT('delivery'),c.deliveryDate,'date')}${owField('ocPayment',owT('payment'),c.paymentTerms,'textarea')}${owField('ocTerms',owT('terms'),c.terms,'textarea',true)}</div><p class="micro">${owT('unitPrice')} → ${owT('articleDiscount')} → ${owT('discount')}. EUR.</p><div class="table-wrap"><table class="table"><thead><tr><th>${t('article')}</th><th>${owT('unitPrice')}</th><th>${owT('articleDiscount')}</th></tr></thead><tbody>${state.products.filter(p=>p.id!=='bespoke').map(p=>`<tr><td>${esc(p.article)}<br>${esc(p.name)}</td><td><input type="number" min="0" step="0.01" id="ocPrice-${p.id}" value="${c.prices[p.id]?.price??''}" aria-label="${owT('unitPrice')} ${esc(p.article)}"></td><td><input type="number" min="0" max="100" step="0.01" id="ocDiscount-${p.id}" value="${c.prices[p.id]?.discount??''}" aria-label="${owT('articleDiscount')} ${esc(p.article)}"></td></tr>`).join('')}</tbody></table></div><p id="owFormError" role="alert" class="ow-error"></p><div class="modal-actions"><button class="btn" onclick="owClientSaveUI()">${owT('save')}</button></div>`,'wide')}
function owSaveClient(c){if(state.role!=='brand')throw Error('Brand role required');if(!c.name.trim()||!c.contactName.trim()||!c.country.trim()||!c.city.trim()||!['person','company'].includes(c.kind)||!Number.isFinite(c.discount)||c.discount<0||c.discount>100)throw Error('Client / contact / geography / discount');for(const [pid,r] of Object.entries(c.prices)){if(!state.products.some(p=>p.id===pid)||r.price!=null&&(!Number.isFinite(r.price)||r.price<0)||r.discount!=null&&(!Number.isFinite(r.discount)||r.discount<0||r.discount>100)||r.price!=null&&r.discount!=null)throw Error('One article price OR discount')};c.id=c.id||owId('C');c.active=true;const i=state.orderDesk.clients.findIndex(x=>x.id===c.id);if(i>=0)state.orderDesk.clients[i]={...state.orderDesk.clients[i],...c};else state.orderDesk.clients.push(c);if(c.id===state.orderDesk.activeClientId){state.buyerProfile.name=c.name;state.buyerProfile.discount=c.discount;state.buyerProfile.terms=c.paymentTerms;state.draftMeta.client=c.name}save();return c.id}
function owClientSaveUI(){const v=id=>document.getElementById(id).value.trim();try{const prices={};for(const p of state.products.filter(p=>p.id!=='bespoke')){const a=v('ocPrice-'+p.id),b=v('ocDiscount-'+p.id);if(a!==''||b!=='')prices[p.id]={...(a!==''?{price:Number(a)}:{}),...(b!==''?{discount:Number(b)}:{})}}owSaveClient({id:v('ocId'),kind:v('ocKind'),name:v('ocName'),legalName:v('ocLegal'),contactName:v('ocContact'),email:v('ocEmail'),phone:v('ocPhone'),city:v('ocCity'),country:v('ocCountry'),discount:Number(v('ocDiscount')),prices,terms:v('ocTerms'),paymentTerms:v('ocPayment'),deliveryDate:v('ocDelivery')});closeOverlay();renderAll();toast(owT('saved'))}catch(e){owFormError(e.message)}}
function owSetsFor(pid){return state.orderDesk.sets.filter(s=>s.active&&s.productIds.includes(pid))}
function owSetCard(s){const ps=s.productIds.map(id=>state.products.find(p=>p.id===id&&p.active)).filter(Boolean);if(ps.length!==s.productIds.length)return '';return `<article class="ow-set"><div class="ow-set-images">${ps.map(p=>`<img src="${esc(owCover(p))}" alt="${esc(p.name)}" loading="lazy">`).join('')}</div><div><div class="eyebrow">${owT('sets')}</div><h3>${esc(s.name)}</h3><p class="micro">${owT('setTogether')}</p><p>${esc(s.description||'')}</p><p class="micro">${ps.map(p=>esc(p.article)).join(' + ')} · ${money(ps.reduce((a,p)=>a+owPrice(p),0))} / 1 + 1</p><button class="btn small" onclick="owOrderSet('${s.id}')">${owT('orderSet')}</button></div></article>`}
function owOrderSet(id){const s=state.orderDesk.sets.find(x=>x.id===id&&x.active);if(!s||s.productIds.some(id=>!state.products.find(p=>p.id===id)?.active))return false;for(const pid of s.productIds){const p=state.products.find(p=>p.id===pid),color=p.colors[0][0],size=p.sizes[Math.floor(p.sizes.length/2)];state.draft[pid]??={};state.draft[pid][color]??={};state.draft[pid][color][size]=(state.draft[pid][color][size]||0)+1;owLog('set',pid)}state.quickFilters.search='';state.quickSavedOnly=false;state.quickAssortmentOnly=false;save();go('quick');return true}
function owSetForm(id){if(state.role!=='brand')return;const s=state.orderDesk.sets.find(x=>x.id===id)||{id:'',name:'',description:'',productIds:[],active:true};modal(owFormHead(owT('sets'))+`<input id="osId" type="hidden" value="${s.id}"><div class="form-grid">${owField('osName',owT('setName'),s.name,'text',true)}${owField('osDescription',t('description'),s.description,'textarea',true)}<div class="full"><div class="ow-label">${owT('setProducts')}</div>${state.products.filter(p=>p.id!=='bespoke').map(p=>`<label class="ow-check"><input type="checkbox" class="osProduct" value="${p.id}" ${s.productIds.includes(p.id)?'checked':''}>${esc(p.name)} · ${esc(p.article)}</label>`).join('')}</div><label class="ow-check"><input type="checkbox" id="osActive" ${s.active?'checked':''}>${owT('active')}</label></div><p class="micro">${owT('setHint')}</p><p id="owFormError" role="alert" class="ow-error"></p><button class="btn" onclick="owSetSaveUI()">${owT('save')}</button>`)}
function owSetSaveUI(){try{if(state.role!=='brand')return;const s={id:document.getElementById('osId').value||owId('SET'),name:document.getElementById('osName').value.trim(),description:document.getElementById('osDescription').value.trim(),productIds:Array.from(document.querySelectorAll('.osProduct:checked')).map(x=>x.value),active:document.getElementById('osActive').checked};if(!s.name||s.productIds.length<2)throw Error('Set name + 2 articles');const i=state.orderDesk.sets.findIndex(x=>x.id===s.id);if(i>=0)state.orderDesk.sets[i]=s;else state.orderDesk.sets.push(s);save();closeOverlay();renderAll()}catch(e){owFormError(e.message)}}
function owRequestForm(pid){const p=state.products.find(x=>x.id===pid&&x.active);if(!p)return;modal(owFormHead(owT('request'))+`<input type="hidden" id="orProduct" value="${pid}"><p>${esc(p.name)} · ${esc(p.article)} · ${esc(owClient().name)}</p><div class="form-grid">${owField('orColor',owT('requestedColor'),'')}${owField('orFabric',owT('requestedFabric'),'')}${owField('orSize',t('sizes'),p.sizes[Math.floor(p.sizes.length/2)])}${owField('orQty',owT('volume'),1,'number')}${owField('orDelivery',owT('delivery'),'','date')}${owField('orNotes',t('notes'),'','textarea',true)}</div><p id="owFormError" role="alert" class="ow-error"></p><button class="btn" onclick="owRequestSaveUI()">${t('send')}</button>`)}
function owRequestSaveUI(){const v=id=>document.getElementById(id).value.trim();try{const r={id:owId('RQ'),clientId:state.orderDesk.activeClientId,productId:v('orProduct'),color:v('orColor'),composition:v('orFabric'),size:v('orSize'),qty:Number(v('orQty')),requestedDelivery:v('orDelivery'),notes:v('orNotes'),status:'requested',at:new Date().toISOString(),history:[]};if(!r.color&&!r.composition||!r.size||!Number.isSafeInteger(r.qty)||r.qty<=0)throw Error('Colour or composition / size / positive integer quantity');state.orderDesk.requests.unshift(r);owLog('custom-request',r.productId);save();closeOverlay();toast(owT('saved'));renderPortal();renderAdmin()}catch(e){owFormError(e.message)}}
function owQuoteForm(id){if(state.role!=='brand')return;const r=state.orderDesk.requests.find(x=>x.id===id);if(!r||r.orderId)return;modal(owFormHead(owT('reply'))+`<input id="oqId" type="hidden" value="${id}"><p>${esc(owClient(r.clientId).name)} · ${esc(r.color)} · ${esc(r.composition)} · ${r.qty}</p><div class="form-grid">${owField('oqColor',t('colors'),r.color||'')}${owField('oqComposition',owT('composition'),r.composition||'')}${owField('oqPrice',owT('unitPrice'),r.unit??'','number')}${owField('oqDelivery',owT('delivery'),r.deliveryDate||'','date')}${owField('oqReply',owT('reply'),r.reply||'','textarea',true)}<div><label class="ow-label" for="oqStatus">${t('status')}</label><select id="oqStatus" class="field"><option value="offered">${owT('offered')}</option><option value="declined">${owT('declined')}</option></select></div></div><p id="owFormError" role="alert" class="ow-error"></p><button class="btn" onclick="owQuoteSaveUI()">${owT('save')}</button>`)}
function owQuote(id,price,date,reply,status='offered',variant=null){const r=state.orderDesk.requests.find(x=>x.id===id);if(state.role!=='brand'||!r||r.orderId||!reply.trim()||status==='offered'&&(!Number.isFinite(price)||price<0||!date))throw Error('Quote price / date / comment');if(variant){r.originalRequested=r.originalRequested||{color:r.color,composition:r.composition};r.color=variant.color;r.composition=variant.composition}r.unit=owRound(price||0);r.deliveryDate=date;r.reply=reply;r.status=status;r.history.push({at:new Date().toISOString(),actor:'Brand Team',status,unit:r.unit,date,reply});save();return true}
function owQuoteSaveUI(){try{owQuote(document.getElementById('oqId').value,Number(document.getElementById('oqPrice').value),document.getElementById('oqDelivery').value,document.getElementById('oqReply').value,document.getElementById('oqStatus').value,{color:document.getElementById('oqColor').value,composition:document.getElementById('oqComposition').value});closeOverlay();renderAll()}catch(e){owFormError(e.message)}}
function owAcceptRequest(id){const r=state.orderDesk.requests.find(x=>x.id===id);if(!r||r.status!=='offered'||r.clientId!==state.orderDesk.activeClientId||state.role==='brand')return false;r.status='accepted';r.history.push({at:new Date().toISOString(),actor:owClient().contactName,status:'accepted'});const p=state.products.find(x=>x.id===r.productId);state.customDraft=(state.customDraft||[]).filter(x=>x.requestId!==id);state.customDraft.push(owSnapshot({productId:r.productId,requestId:id,color:r.color||p.colors[0][0],size:r.size,composition:r.composition||p.composition,qty:r.qty,unit:r.unit,deliveryDate:r.deliveryDate}));save();go('quick');return true}
function owRequestCards(brand=false){const rs=state.orderDesk.requests.filter(r=>brand||r.clientId===state.orderDesk.activeClientId);return rs.length?`<div class="ow-grid">${rs.map(r=>{const p=state.products.find(p=>p.id===r.productId);return `<article class="ow-card"><div class="eyebrow">${esc(p?.article)} · ${esc(owClient(r.clientId)?.name)}</div><h3>${esc(p?.name)}</h3><p>${esc(r.color||'—')} · ${esc(r.composition||'—')} · ${esc(r.size)} · ${r.qty}</p><p class="micro">${esc(r.notes)} · ${fmtDate(r.at)}</p><span class="status">${owT(r.status)}</span>${r.reply?`<p>${esc(r.reply)}</p><p>${money(r.unit)} · ${esc(r.deliveryDate||'')}</p>`:''}<div class="cta-row">${brand&&!r.orderId?`<button class="btn small" onclick="owQuoteForm('${r.id}')">${owT('reply')}</button>`:''}${!brand&&r.status==='offered'?`<button class="btn small" onclick="owAcceptRequest('${r.id}')">${owT('customDraft')}</button>`:''}${r.orderId?`<span class="micro">${esc(r.orderId)}</span>`:''}</div></article>`}).join('')}</div>`:`<div class="empty">${owT('noData')}</div>`}
function owOrderEdit(id){if(state.role!=='brand')return;const o=state.orders.find(o=>o.id===id);if(!o||o.status==='cancelled')return;modal(owFormHead(owT('edit')+' · '+o.id)+`<input id="oeId" type="hidden" value="${id}"><p class="micro">${owT('snapshot')}</p><div class="form-grid">${owField('oeReason',owT('reason'),'','textarea',true)}${owField('oeDelivery',owT('delivery'),/^\d{4}-\d{2}-\d{2}$/.test(o.delivery)?o.delivery:'','date')}${owField('oeDiscount',owT('orderDiscount'),o.discount||0,'number')}${owField('oeTerms',owT('terms'),o.terms,'textarea')}${owField('oePayment',owT('payment'),o.paymentTerms,'textarea')}${owField('oeNotes',t('notes'),o.notes,'textarea',true)}</div><div class="table-wrap"><table class="table"><thead><tr><th>${t('article')}</th><th>${owT('volume')}</th><th>${owT('unitPrice')}</th><th>${owT('delivery')}</th></tr></thead><tbody>${o.lines.map((l,i)=>`<tr><td>${esc(l.article)} · ${esc(l.color)} · ${esc(l.size)}<br>${esc(l.composition)}</td><td><input id="oeQty-${i}" type="number" min="0" step="1" value="${l.qty}" aria-label="${owT('volume')} ${i+1}"></td><td><input id="oePrice-${i}" type="number" min="0" step="0.01" value="${l.unit}" aria-label="${owT('unitPrice')} ${i+1}"></td><td><input id="oeDate-${i}" type="date" value="${l.deliveryDate||''}" aria-label="${owT('delivery')} ${i+1}"></td></tr>`).join('')}</tbody></table></div><p id="owFormError" role="alert" class="ow-error"></p><div class="modal-actions"><button class="btn secondary" onclick="owRepriceEditor()">${owT('reprice')}</button><button class="btn" onclick="owOrderEditSaveUI()">${owT('save')}</button></div>`,'wide')}
function owRepriceEditor(){const o=state.orders.find(o=>o.id===document.getElementById('oeId').value);o.lines.forEach((l,i)=>{if(!l.requestId)document.getElementById('oePrice-'+i).value=owPrice(state.products.find(p=>p.id===l.productId),o.clientId)})}
function owEditOrder(id,patch,reason){const o=state.orders.find(o=>o.id===id);if(state.role!=='brand'||!o||o.status==='cancelled'||!reason.trim()||!patch.lines.length||patch.lines.some(l=>!Number.isSafeInteger(l.qty)||l.qty<=0||!Number.isFinite(l.unit)||l.unit<0)||!Number.isFinite(patch.discount)||patch.discount<0||patch.discount>100)throw Error('Revision comment / units / price / discount');owRevise(o,reason);Object.assign(o,patch,{updated:new Date().toISOString()});save();return true}
function owOrderEditSaveUI(){try{const id=document.getElementById('oeId').value,o=state.orders.find(o=>o.id===id);const lines=o.lines.map((l,i)=>({...l,qty:Number(document.getElementById('oeQty-'+i).value),unit:Number(document.getElementById('oePrice-'+i).value),deliveryDate:document.getElementById('oeDate-'+i).value}));if(lines.some(l=>!Number.isSafeInteger(l.qty)||l.qty<0))throw Error('Integer quantity');owEditOrder(id,{lines:lines.filter(l=>l.qty>0),delivery:document.getElementById('oeDelivery').value,discount:Number(document.getElementById('oeDiscount').value),terms:document.getElementById('oeTerms').value,paymentTerms:document.getElementById('oePayment').value,notes:document.getElementById('oeNotes').value},document.getElementById('oeReason').value);closeOverlay();renderOrders();renderAdmin()}catch(e){owFormError(e.message)}}
function owMatchOrder(o,f=state.orderDesk.filters){const c=o.clientSnapshot||owClient(o.clientId);return(f.clientId==='All'||o.clientId===f.clientId)&&(f.kind==='All'||c?.kind===f.kind)&&(f.country==='All'||c?.country===f.country)&&(f.city==='All'||c?.city===f.city)&&(f.status==='All'||o.status===f.status)}
function owEntries(){const f=state.orderDesk.filters;return state.orders.filter(o=>owMatchOrder(o)).flatMap(o=>o.lines.filter(l=>f.season==='All'||l.season===f.season).map(l=>({o,l,client:o.clientSnapshot||owClient(o.clientId),value:owRound(l.qty*l.unit*(1-(o.discount||0)/100))})))}
function owGroups(entries,group=state.orderDesk.filters.group){const map=new Map();for(const e of entries){const key=group==='stores'?e.o.clientId:group==='countries'?e.client?.country:group==='cities'?e.client?.city:e.l.productId+'|'+e.l.article;const label=group==='stores'?e.client?.name:group==='countries'?e.client?.country:group==='cities'?e.client?.city:e.l.article+' · '+e.l.name;if(!map.has(key))map.set(key,{key,label:label||'—',units:0,value:0,orders:new Set()});const r=map.get(key);r.units+=e.l.qty;r.value+=e.value;r.orders.add(e.o.id)}return [...map.values()].map(r=>({...r,value:owRound(r.value),orders:r.orders.size})).sort((a,b)=>b.value-a.value)}
function owSetFilter(k,v){state.orderDesk.filters[k]=v;save();renderAdmin()}
function owFilters(){const f=state.orderDesk.filters,cs=state.orderDesk.clients;const dims=[['season',owT('season'),[...new Set(state.orders.flatMap(o=>o.lines.map(l=>l.season)).concat(state.products.map(p=>p.season||p.collection)))]],['clientId',owT('client'),cs.map(c=>[c.id,c.name])],['country',owT('country'),[...new Set(cs.map(c=>c.country))]],['city',owT('city'),[...new Set(cs.map(c=>c.city))]],['kind',owT('client'),[['company',owT('company')],['person',owT('person')]]],['status',t('status'),['draft','submitted','inReview','offer','confirmed','cancelled'].map(s=>[s,owStatus(s)])]];return `<div class="filters ow-filters">${dims.map(([k,l,vals])=>`<label class="field"><span class="ow-label">${l}</span><select aria-label="${l}" onchange="owSetFilter('${k}',this.value)"><option value="All">${owT('all')}</option>${vals.map(x=>{const [v,n]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${f[k]===v?'selected':''}>${esc(n)}</option>`}).join('')}</select></label>`).join('')}</div>`}
function owDashboard(){const es=owEntries(),confirmed=es.filter(e=>owConfirmed(e.o)),pending=es.filter(e=>['submitted','inReview','offer'].includes(e.o.status)),f=state.orderDesk.filters;const tabs=['articles','stores','countries','cities'];return owFilters()+`<p class="micro">${owT('noRevenue')}</p><div class="ow-kpis">${[[owT('confirmed'),money(confirmed.reduce((n,e)=>n+e.value,0))],[owT('volume'),confirmed.reduce((n,e)=>n+e.l.qty,0)],[owT('orders'),new Set(confirmed.map(e=>e.o.id)).size],[owT('potential'),money(pending.reduce((n,e)=>n+e.value,0))]].map(([l,v])=>`<div class="metric"><span>${l}</span><strong>${v}</strong></div>`).join('')}</div><div class="admin-head"><h3>${owT('confirmed')}</h3><button class="btn small secondary" onclick="owExportReport()">${owT('report')}</button></div><label class="field">${owT('statsBy')}<select onchange="owSetFilter('group',this.value)">${tabs.map(k=>`<option value="${k}" ${f.group===k?'selected':''}>${owT(k)}</option>`).join('')}</select></label><div class="table-wrap"><table class="table"><thead><tr><th>${owT(f.group)}</th><th>${owT('orders')}</th><th>${owT('volume')}</th><th>${owT('value')}</th></tr></thead><tbody>${owGroups(confirmed).map(r=>`<tr><td>${esc(r.label)}</td><td>${r.orders}</td><td>${r.units}</td><td>${money(r.value)}</td></tr>`).join('')||`<tr><td colspan="4">${owT('noData')}</td></tr>`}</tbody></table></div><div class="sep"></div><h3>${owT('potential')}</h3>${owOrderTable(state.orders.filter(o=>owMatchOrder(o)&&['submitted','inReview','offer'].includes(o.status)&&o.lines.some(l=>f.season==='All'||l.season===f.season)))}`}
function owOrderTable(os){return `<div class="table-wrap"><table class="table"><thead><tr><th>${t('orderNo')}</th><th>${owT('client')}</th><th>${owT('contact')}</th><th>${owT('city')} / ${owT('country')}</th><th>${t('status')}</th><th>${owT('volume')}</th><th>${owT('value')}</th><th>${owT('delivery')}</th></tr></thead><tbody>${os.map(o=>{const c=o.clientSnapshot||owClient(o.clientId);return `<tr><td><button class="ow-link" onclick="state.selectedOrder='${o.id}';go('orders')">${esc(o.id)}</button><div class="micro">${owT('revision')} ${o.revision}</div></td><td>${esc(c?.name)}<div class="micro">${owT(c?.kind==='company'?'company':'person')}</div></td><td>${esc(c?.contactName)}</td><td>${esc(c?.city)} · ${esc(c?.country)}</td><td>${owStatus(o.status)}</td><td>${orderUnits(o)}</td><td>${money(orderValue(o))}</td><td>${esc(o.delivery||owT('dateUnknown'))}</td></tr>`}).join('')||`<tr><td colspan="8">${owT('noData')}</td></tr>`}</tbody></table></div>`}
function owAdminProducts(){return `<div class="admin-head"><h3>${owT('products')}</h3><button class="btn small" onclick="owProductForm()">+ ${owT('add')}</button></div><div class="ow-grid">${state.products.filter(p=>p.id!=='bespoke').map(p=>`<article class="ow-card"><img class="ow-product-cover" src="${esc(owCover(p))}" alt="${esc(p.name)}" loading="lazy"><div class="eyebrow">${esc(p.article)} · ${esc(p.season||p.collection)}</div><h3>${esc(p.name)}</h3><p class="micro">${esc(p.composition)}<br>${p.sizes.map(esc).join(' / ')}<br>${esc(owDelivery(p))}</p><p>${money(p.b2b)} / ${money(p.b2c)}</p><span class="status">${owT(p.active?'active':'inactive')}</span><div class="cta-row"><button class="btn small" onclick="owProductForm('${p.id}')">${owT('edit')}</button><button class="btn small secondary" onclick="owToggleProduct('${p.id}')">${owT(p.active?'deactivate':'activate')}</button><button class="btn small secondary" onclick="owProduct('${p.id}',true)">${owT('preview')}</button></div></article>`).join('')}</div>`}
function owAdminClients(){return `<div class="admin-head"><h3>${owT('clients')}</h3><button class="btn small" onclick="owClientForm()">+ ${owT('add')}</button></div><div class="ow-grid">${state.orderDesk.clients.map(c=>{const os=state.orders.filter(o=>o.clientId===c.id&&owConfirmed(o));const wl=state.orderDesk.wishlists[c.id]||[];return `<article class="ow-card"><div class="eyebrow">${owT(c.kind==='company'?'company':'person')}</div><h3>${esc(c.name)}</h3><p>${esc(c.legalName||'')}<br>${esc(c.contactName)}<br>${esc(c.city)} · ${esc(c.country)}</p><p class="micro">${esc(c.email)} · ${esc(c.phone)}</p><p>${owT('discount')}: ${c.discount}% · ${Object.keys(c.prices).length} ${owT('articles')}</p><p class="micro">${esc(c.terms)}<br>${esc(c.paymentTerms)}</p><p>${owT('confirmed')}: ${money(os.reduce((a,o)=>a+orderValue(o),0))}<br>${owT('wishlist')}: ${wl.length}</p><div class="cta-row"><button class="btn small" onclick="owClientForm('${c.id}')">${owT('edit')}</button><button class="btn small secondary" onclick="owClientOrders('${c.id}')">${owT('orders')}</button><button class="btn small secondary" onclick="owActivate('${c.id}');setRole(owClient().kind==='company'?'buyer':'private');go('portal')">${owT('preview')}</button></div></article>`}).join('')}</div>`}
function owClientOrders(id){state.orderDesk.filters.clientId=id;state.orderDesk.adminTab='orders';save();renderAdmin()}
function owInterest(){const f=state.orderDesk.filters;const cs=state.orderDesk.clients.filter(c=>(f.clientId==='All'||f.clientId===c.id)&&(f.country==='All'||c.country===f.country)&&(f.city==='All'||c.city===f.city)&&(f.kind==='All'||c.kind===f.kind));const ps=state.products.filter(p=>f.season==='All'||(p.season||p.collection)===f.season);const rows=cs.flatMap(c=>ps.map(p=>{const events=state.orderDesk.activity.filter(x=>x.clientId===c.id&&x.productId===p.id),saved=(state.orderDesk.wishlists[c.id]||[]).includes(p.id),placed=state.orders.some(o=>o.clientId===c.id&&!['draft','cancelled'].includes(o.status)&&o.lines.some(l=>l.productId===p.id));return{c,p,events,views:events.filter(x=>x.type==='view').length,saved,placed}}).filter(x=>x.views||x.saved||x.events.some(e=>e.type==='matrix')));const opportunities=rows.filter(x=>x.saved&&!x.placed);return owFilters()+`<div class="ow-kpis"><div class="metric"><span>${owT('views')}</span><strong>${rows.reduce((n,r)=>n+r.views,0)}</strong></div><div class="metric"><span>${owT('wishlist')}</span><strong>${rows.filter(r=>r.saved).length}</strong></div><div class="metric"><span>${owT('notOrdered')}</span><strong>${opportunities.length}</strong></div></div><p class="micro">${owT('demo')} · ${owT('notOrdered')}: ${owT('client')} × ${t('article')}, ${owT('value')} — ${owT('noData')}.</p><div class="table-wrap"><table class="table"><thead><tr><th>${owT('client')}</th><th>${owT('contact')}</th><th>${owT('city')} / ${owT('country')}</th><th>${t('article')}</th><th>${owT('views')}</th><th>${owT('wishlist')}</th><th>${owT('ordered')}</th><th>${owT('lastAction')}</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.c.name)}</td><td>${esc(r.c.contactName)}</td><td>${esc(r.c.city)} · ${esc(r.c.country)}</td><td><button class="ow-link" onclick="owProduct('${r.p.id}',true)">${esc(r.p.article)} · ${esc(r.p.name)}</button></td><td>${r.views}</td><td>${r.saved?'♥':'—'}</td><td>${r.placed?'✓':r.saved?owT('notOrdered'):'—'}</td><td>${r.events.length?fmtDate(r.events[0].at):'—'}</td></tr>`).join('')||`<tr><td colspan="8">${owT('noData')}</td></tr>`}</tbody></table></div><details><summary>${owT('history')}</summary><div class="table-wrap"><table class="table"><thead><tr><th>${owT('client')}</th><th>${t('article')}</th><th>${owT('lastAction')}</th><th>${t('dates')}</th></tr></thead><tbody>${state.orderDesk.activity.filter(e=>cs.some(c=>c.id===e.clientId)&&(!e.productId||ps.some(p=>p.id===e.productId))).slice(0,100).map(e=>`<tr><td>${esc(owClient(e.clientId)?.contactName)} · ${esc(owClient(e.clientId)?.name)}</td><td>${esc(state.products.find(p=>p.id===e.productId)?.article||'—')}</td><td>${esc(e.type)}</td><td>${fmtDate(e.at)}</td></tr>`).join('')}</tbody></table></div></details>`}
function owCollectionForm(id){if(state.role!=='brand')return;const c=state.collections.find(c=>c.id===id)||{id:'',name:'',audience:'Both',story:'',dates:'',status:'Active',deliveryDate:'',deliveryEnd:''};modal(owFormHead(owT('collections'))+`<input id="oclId" type="hidden" value="${c.id}"><div class="form-grid">${owField('oclName',t('collectionName'),c.name)}${owField('oclDates',owT('season'),c.dates)}${owField('oclStart',owT('delivery'),c.deliveryDate,'date')}${owField('oclEnd',owT('deliveryEnd'),c.deliveryEnd,'date')}${owField('oclStory',t('story'),c.story,'textarea',true)}</div><p id="owFormError" role="alert" class="ow-error"></p><button class="btn" onclick="owCollectionSaveUI()">${owT('save')}</button>`)}
function owCollectionSaveUI(){try{if(state.role!=='brand')return;const v=id=>document.getElementById(id).value;const id=v('oclId')||owId('COL'),old=state.collections.find(c=>c.id===id);const c={...old,id,name:v('oclName').trim(),dates:v('oclDates'),deliveryDate:v('oclStart'),deliveryEnd:v('oclEnd'),story:v('oclStory'),audience:old?.audience||'Both',status:old?.status||'Active'};if(!c.name||state.collections.some(x=>x.name===c.name&&x.id!==id)||c.deliveryDate&&c.deliveryEnd&&c.deliveryEnd<c.deliveryDate)throw Error('Unique name / delivery window');if(old){if(old.name!==c.name)state.products.filter(p=>p.collection===old.name).forEach(p=>p.collection=c.name);Object.assign(old,c)}else state.collections.push(c);save();closeOverlay();renderAll()}catch(e){owFormError(e.message)}}
function owAdminCollections(){return `<div class="admin-head"><h3>${owT('collections')}</h3><button class="btn small" onclick="owCollectionForm()">+ ${owT('add')}</button></div><div class="ow-grid">${state.collections.map(c=>`<article class="ow-card"><h3>${esc(c.name)}</h3><p>${esc(c.story)}</p><p>${esc(c.deliveryDate||owT('dateUnknown'))} ${esc(c.deliveryEnd||'')}</p><button class="btn small" onclick="owCollectionForm('${c.id}')">${owT('edit')}</button></article>`).join('')}</div>`}
function owCSVCell(v){let s=String(v??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}
function owDownload(name,rows){const csv='\ufeff'+rows.map(r=>r.map(owCSVCell).join(';')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function owReportRows(){const f=state.orderDesk.filters;return [['Marco Pescarolo','Order Workspace v2',new Date().toISOString()],['Scope',JSON.stringify(f)],['Order','Status','Revision','Client type','Client','Contact','Country','City','Season','Article','Product','Color','Size','Composition','Qty','Unit EUR','Order discount %','Net line EUR','Delivery','Created','Terms'],...owEntries().map(e=>[e.o.id,e.o.status,e.o.revision,e.client?.kind,e.client?.name,e.client?.contactName,e.client?.country,e.client?.city,e.l.season,e.l.article,e.l.name,e.l.color,e.l.size,e.l.composition,e.l.qty,e.l.unit,e.o.discount||0,e.value,e.l.deliveryDate||e.o.delivery,e.o.created,e.o.terms]),['Confirmed value EUR',owRound(owEntries().filter(e=>owConfirmed(e.o)).reduce((n,e)=>n+e.value,0))],['Note',owT('noRevenue')]]}
function owExportReport(){owDownload('Marco-Pescarolo-orders.csv',owReportRows())}
function owOrderExport(id){const o=owVisibleOrders().find(o=>o.id===id);if(!o)return;const c=o.clientSnapshot||owClient(o.clientId);owDownload('Marco-Pescarolo-'+o.id+'.csv',[['Order',o.id,'Revision',o.revision,'Status',o.status],['Client',c.name,'Contact',c.contactName,c.city,c.country],['Terms',o.terms,'Payment terms',o.paymentTerms,'Delivery',o.delivery],['Season','Article','Product','Colour','Size','Composition','Qty','Unit EUR','Order discount %','Net EUR','Delivery'],...o.lines.map(l=>[l.season,l.article,l.name,l.color,l.size,l.composition,l.qty,l.unit,o.discount||0,owRound(l.qty*l.unit*(1-(o.discount||0)/100)),l.deliveryDate||o.delivery]),['TOTAL EUR',orderValue(o),'UNITS',orderUnits(o)],['Note',owT('printHint')]])}
function owPrint(id){const o=owVisibleOrders().find(o=>o.id===id);if(!o)return;document.getElementById('owPrintArea')?.remove();const area=document.createElement('div');area.id='owPrintArea';area.innerHTML=owOrderHtml(o,true);document.body.append(area);window.print()}
function owOrderHtml(o,print=false){const c=o.clientSnapshot||owClient(o.clientId);return `<div class="ow-order"><div class="detail-head"><div><div class="eyebrow">${owT('revision')} ${o.revision} · ${owStatus(o.status)}</div><h2>${esc(o.id)}</h2><p>${esc(c?.name)} · ${owT(c?.kind==='company'?'company':'person')}<br>${esc(c?.contactName)} · ${esc(c?.city)} · ${esc(c?.country)}<br>${esc(c?.email||'')}</p></div>${print?'':`<div class="ow-actions"><button class="btn small secondary" onclick="owOrderExport('${o.id}')">${owT('exportOrder')}</button><button class="btn small secondary" onclick="owPrint('${o.id}')">${owT('print')}</button></div>`}</div><div class="ow-kpis"><div class="stat"><span>${owT('volume')}</span><strong>${orderUnits(o)}</strong></div><div class="stat"><span>${owT('value')}</span><strong>${money(orderValue(o))}</strong></div><div class="stat"><span>${owT('orderDiscount')}</span><strong>${o.discount||0}%</strong></div><div class="stat"><span>${owT('delivery')}</span><strong>${esc(o.delivery||owT('dateUnknown'))}</strong></div></div><p class="micro">${owT('snapshot')}</p><p>${esc(o.terms)}<br>${esc(o.paymentTerms)}<br>${esc(o.notes)}</p><div class="table-wrap"><table class="table"><thead><tr><th>${owT('season')} / ${t('article')}</th><th>${owT('composition')}</th><th>${t('colors')} / ${t('sizes')}</th><th>${owT('volume')}</th><th>${owT('unitPrice')}</th><th>${owT('value')}</th><th>${owT('delivery')}</th></tr></thead><tbody>${o.lines.map(l=>`<tr><td>${esc(l.season)}<br>${esc(l.article)}<br>${esc(l.name)}${l.requestId?'<br>'+owT('requests'):''}</td><td>${esc(l.composition)}</td><td>${esc(l.color)} / ${esc(l.size)}</td><td>${l.qty}</td><td>${money(l.unit)}</td><td>${money(owRound(l.qty*l.unit*(1-(o.discount||0)/100)))}</td><td>${esc(l.deliveryDate||o.delivery||owT('dateUnknown'))}</td></tr>`).join('')}</tbody></table></div>${print?`<p>${owT('printHint')}</p>`:`<div class="cta-row">${state.role==='brand'&&o.status!=='cancelled'?`<button class="btn small secondary" onclick="owOrderEdit('${o.id}')">${owConfirmed(o)?owT('reopen'):owT('edit')}</button>`:''}${state.role==='brand'&&['submitted','inReview'].includes(o.status)?`<button class="btn small" onclick="owOffer('${o.id}')">${owT('finalize')}</button>`:''}${state.role!=='brand'&&o.status==='offer'?`<button class="btn small" onclick="owAccept('${o.id}')">${owT('accept')}</button>`:''}${state.role==='brand'&&o.status!=='cancelled'?`<button class="btn small secondary" onclick="owCancel('${o.id}')">${owT('cancelled')}</button>`:''}${o.status==='draft'&&state.role!=='brand'?`<button class="btn small" onclick="owLoadDraft('${o.id}')">${owT('edit')}</button>`:''}</div><div class="sep"></div><h3>${owT('history')}</h3>${(o.audit||[]).map(a=>`<div class="ow-audit"><strong>${esc(a.actor)} · ${esc(a.action)}</strong><p class="micro">${fmtDate(a.at)} · ${esc(a.comment||'')}</p></div>`).join('')||'<p class="micro">—</p>'}<div class="sep"></div><h3>${t('messages')}</h3><div class="thread">${o.messages.map(m=>`<div class="message ${m.from==='brand'?'':'mine'}">${esc(m.text)}<small>${m.from==='brand'?owT('admin'):esc(c?.contactName)} · ${fmtDate(m.at)}</small></div>`).join('')}<div class="compose"><input id="msgInput" aria-label="${t('messages')}" placeholder="${t('typeMessage')}"><button onclick="sendMessage('${o.id}')">${t('send')}</button></div>${state.role==='brand'?`<details><summary>${t('internalNote')}</summary>${o.internal.map(m=>`<p class="micro">${esc(m.text)} · ${fmtDate(m.at)}</p>`).join('')}<div class="internal-note"><input id="noteInput" aria-label="${t('internalNote')}" placeholder="${t('typeInternal')}"><button onclick="addInternal('${o.id}')">${t('addNote')}</button></div></details>`:''}</div>`}</div>`}
function owProduct(pid,preview=false){const p=state.products.find(p=>p.id===pid);if(!p||!p.active&&!(preview&&state.role==='brand'))return;if(!preview)owLog('view',pid);const sets=owSetsFor(pid);modal(`<div class="modal-head"><div><div class="eyebrow">${esc(p.article)} · ${esc(p.season||p.collection)}</div><h2>${esc(p.name)}</h2></div><button class="x" onclick="closeOverlay()">×</button></div><div class="ow-product-detail">${owMediaHtml(p)}<div><p class="lead">${esc(p.description)}</p><dl class="ow-spec">${[[owT('composition'),p.composition],[owT('fit'),p.fit],[owT('care'),p.care],[owT('origin'),p.origin],[owT('delivery'),owDelivery(p)],[owT('details'),p.details]].filter(([k,v])=>v).map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl><div class="chips">${p.colors.map(c=>`<span class="chip">${esc(c[0])}</span>`).join('')}</div><p>${p.sizes.map(esc).join(' / ')}</p><h3>${money(owPrice(p))}</h3>${p.active?`<div class="cta-row"><button class="btn" onclick="closeOverlay();go('quick');setQuickProduct('${p.id}')">${t('openQuick')}</button><button class="btn secondary" onclick="owRequestForm('${p.id}')">${owT('request')}</button><button class="btn secondary" onclick="owWishlist('${p.id}');owProduct('${p.id}')">${isFav(p.id)?'♥':'♡'} ${owT('wishlist')}</button></div>`:''}</div></div>${sets.length?`<div class="sep"></div><h3>${owT('sets')}</h3><p class="micro">${owT('setHint')}</p>${sets.map(owSetCard).join('')}`:''}`,'wide')}
function owProductCard(p){const sets=owSetsFor(p.id);return `<article class="product"><div class="product-img has-photo" style="background-image:url('${esc(owCover(p))}')"><div class="badge">${esc(p.season||p.collection)}</div><button class="fav-btn ${isFav(p.id)?'active':''}" onclick="owWishlist('${p.id}',event)" aria-label="${owT('wishlist')} ${esc(p.name)}">${isFav(p.id)?'♥':'♡'}</button></div><div class="product-body"><div class="product-meta"><span>${esc(p.article)}</span><span>${esc(p.category)}</span></div><h3>${esc(p.name)}</h3><p class="micro">${esc(p.composition)}<br>${esc(owDelivery(p))}</p><div class="price">${money(owPrice(p))}</div>${sets.length?`<p class="ow-set-badge">${owT('sets')} · ${esc(sets[0].name)}</p>`:''}<div class="cta-row"><button class="btn small secondary" onclick="owProduct('${p.id}')">${t('view')}</button><button class="btn small" onclick="go('quick');setQuickProduct('${p.id}')">${t('quick')}</button></div></div></article>`}
function owQuickColor(pid,ci,btn){document.querySelectorAll('#ct-'+pid+' .color-tab').forEach(b=>b.classList.remove('active'));btn.classList.add('active');document.getElementById('qgrid-'+pid).innerHTML=quickGrid(state.products.find(p=>p.id===pid),state.products.find(p=>p.id===pid).colors[ci][0])}
function owQty(pid,ci,si,value,delta=false){const p=state.products.find(p=>p.id===pid),color=p.colors[ci][0],size=p.sizes[si],q=delta?draftQty(pid,color,size)+value:Number(value);if(!Number.isSafeInteger(q)||q<0){toast(owT('invalid'),true);renderQuick();return}state.draft[pid]??={};state.draft[pid][color]??={};state.draft[pid][color][size]=q;owLog('matrix',pid,q);document.getElementById('qgrid-'+pid).innerHTML=quickGrid(p,color);renderQuickProductTotals(pid);renderSummary()}
function owRun(pid,mode){const p=state.products.find(p=>p.id===pid),ci=Number(document.querySelector('#ct-'+pid+' .active')?.dataset.index||0),color=p.colors[ci][0];state.draft[pid]??={};state.draft[pid][color]??={};const vals=mode==='clear'?p.sizes.map(()=>0):sizeRunPattern(p.sizes.length,mode);p.sizes.forEach((s,i)=>state.draft[pid][color][s]=vals[i]);owLog('matrix',pid,vals.reduce((a,b)=>a+b,0));document.getElementById('qgrid-'+pid).innerHTML=quickGrid(p,color);renderQuickProductTotals(pid);renderSummary()}
function owQuickProduct(p){return `<div class="order-product" data-pid="${p.id}"><div class="op-head"><img class="thumb ow-thumb" src="${esc(owCover(p))}" alt="${esc(p.name)}"><div class="op-title"><div class="micro">${esc(p.article)} · ${esc(p.season||p.collection)}</div><h3>${esc(p.name)}</h3><small>${money(owPrice(p))} · ${esc(p.composition)}</small><p class="micro">${owT('delivery')}: ${esc(owDelivery(p))}</p></div><button class="btn small secondary" onclick="owRequestForm('${p.id}')">${owT('requests')}</button></div><div class="color-tabs" id="ct-${p.id}">${p.colors.map((c,i)=>`<button class="color-tab ${i===0?'active':''}" data-index="${i}" onclick="owQuickColor('${p.id}',${i},this)">${esc(c[0])}</button>`).join('')}</div><div id="qgrid-${p.id}">${quickGrid(p,p.colors[0][0])}</div><div class="run-tools"><button onclick="owRun('${p.id}','core')">${t('coreRun')}</button><button onclick="owRun('${p.id}','full')">${t('fullRun')}</button><button onclick="owRun('${p.id}','clear')">${t('clearRun')}</button></div><div class="op-foot"><span>${owSetsFor(p.id).length?owT('setTogether'):''}</span><strong id="ptotal-${p.id}">${productDraftTotalLabel(p.id)}</strong></div></div>`}
function owGrid(p,color){const ci=p.colors.findIndex(c=>c[0]===color);return `<div class="ow-matrix-scroll"><div class="size-grid" style="--size-count:${p.sizes.length}"><div class="size-cell label">${t('sizes')}</div>${p.sizes.map(s=>`<div class="size-cell">${esc(s)}</div>`).join('')}<div class="size-cell label">${esc(color)}</div>${p.sizes.map((s,i)=>`<div class="size-cell"><div class="qty"><button aria-label="− ${esc(s)}" onclick="owQty('${p.id}',${ci},${i},-1,true)">−</button><input inputmode="numeric" value="${draftQty(p.id,color,s)}" aria-label="${esc(p.article)} ${esc(color)} ${esc(s)}" onchange="owQty('${p.id}',${ci},${i},this.value)"><button aria-label="+ ${esc(s)}" onclick="owQty('${p.id}',${ci},${i},1,true)">+</button></div></div>`).join('')}</div></div>`}
function owRemoveDraft(pid){delete state.draft[pid];state.customDraft=state.customDraft.filter(l=>l.productId!==pid);save();renderQuick()}
function owRemoveCustom(id){state.customDraft=state.customDraft.filter(l=>l.requestId!==id);save();renderQuick()}
function owSummary(){const c=owClient(),ls=owDraftLines(),invalid=ls.filter(l=>!owValidateLine(l));document.getElementById('orderSummary').innerHTML=`<div class="eyebrow">${owT('client')}</div><h3>${esc(c.name)}</h3><p class="micro" style="color:#ddd">${esc(c.contactName)} · ${esc(c.city)} · ${esc(c.country)}</p>${owClientSelect('quick')}<div class="sum-row"><span>${owT('units')}</span><strong>${ls.reduce((a,l)=>a+l.qty,0)}</strong></div><div class="sum-row total"><span>${owT('value')}</span><strong>${money(ls.reduce((a,l)=>a+l.qty*l.unit,0))}</strong></div><p class="micro" style="color:#ddd">${esc(c.terms)}<br>${esc(c.paymentTerms)}</p><label class="label" for="draftDelivery">${owT('delivery')}</label><div class="field"><input id="draftDelivery" type="date" value="${state.draftMeta.delivery||''}" onchange="state.draftMeta.delivery=this.value;save()"></div><label class="label" for="draftNotes">${t('notes')}</label><div class="field"><textarea id="draftNotes" oninput="state.draftMeta.notes=this.value;save()">${esc(state.draftMeta.notes||'')}</textarea></div>${invalid.length?`<p class="ow-error">${owT('blocked')}</p>${[...new Set(invalid.map(l=>l.productId))].map(pid=>`<button class="btn secondary" onclick="owRemoveDraft('${pid}')">${owT('remove')} · ${esc(state.products.find(p=>p.id===pid)?.article)}</button>`).join('')}`:''}<button class="btn secondary" onclick="owSaveDraft()">${t('saveDraft')}</button><button class="btn" onclick="owSubmit()" ${invalid.length||!ls.length?'disabled':''}>${t('submitOrder')}</button><p class="micro" style="color:#ddd">${owT('demo')}</p>`;const mobile=document.getElementById('mobileSummary');mobile.classList.toggle('hide',state.page!=='quick');mobile.innerHTML=`<strong>${ls.reduce((a,l)=>a+l.qty,0)} · ${money(ls.reduce((a,l)=>a+l.qty*l.unit,0))}</strong><button onclick="openMobileSummary()">${t('orderSummary')}</button>`}
function owLoadDraft(id){const o=owVisibleOrders().find(o=>o.id===id&&o.status==='draft');if(!o||state.role==='brand')return;state.draft={};state.customDraft=[];for(const l of o.lines){if(l.requestId){state.customDraft.push(l);continue}state.draft[l.productId]??={};state.draft[l.productId][l.color]??={};state.draft[l.productId][l.color][l.size]=l.qty}state.draftMeta={client:o.client,delivery:o.delivery,notes:o.notes};state.draftOrderId=o.id;save();go('quick')}
function owAdmin(){const metrics=document.getElementById('metrics');metrics.innerHTML='';document.getElementById('adminTabs').innerHTML='';const host=document.getElementById('adminContent');if(state.role!=='brand'){host.innerHTML=`<div class="ow-card"><h3>${owT('admin')}</h3><p class="micro">${owT('demo')}</p><button class="btn" onclick="setRole('brand');renderAdmin()">${owT('admin')}</button></div>`;return}const d=state.orderDesk;const tabs=['dashboard','products','clients','orders','interest','requests','sets','collections'];document.getElementById('adminTabs').innerHTML=tabs.map(k=>`<button class="${d.adminTab===k?'active':''}" onclick="state.orderDesk.adminTab='${k}';save();renderAdmin()">${owT(k)}</button>`).join('');host.innerHTML=`<p class="micro">${owT('demo')}</p>`+(d.adminTab==='products'?owAdminProducts():d.adminTab==='clients'?owAdminClients():d.adminTab==='orders'?owFilters()+owOrderTable(state.orders.filter(o=>owMatchOrder(o)&&(d.filters.season==='All'||o.lines.some(l=>l.season===d.filters.season)))):d.adminTab==='interest'?owInterest():d.adminTab==='requests'?owRequestCards(true):d.adminTab==='sets'?`<div class="admin-head"><h3>${owT('sets')}</h3><button class="btn small" onclick="owSetForm()">+ ${owT('add')}</button></div><p class="micro">${owT('setHint')}</p><div class="ow-grid">${d.sets.map(s=>`<article class="ow-card"><h3>${esc(s.name)}</h3><p>${s.productIds.map(id=>esc(state.products.find(p=>p.id===id)?.name)).join(' + ')}</p><span class="status">${owT(s.active?'active':'inactive')}</span><div class="cta-row"><button class="btn small" onclick="owSetForm('${s.id}')">${owT('edit')}</button></div></article>`).join('')}</div>`:d.adminTab==='collections'?owAdminCollections():owDashboard())}
function owPortal(){const c=owClient(),os=state.orders.filter(o=>o.clientId===c.id),wl=state.products.filter(p=>p.active&&isFav(p.id));document.getElementById('buyerPortal').innerHTML=`<div class="portal-card">${owClientSelect('portal')}<h3>${esc(c.name)}</h3><p>${esc(c.contactName)} · ${esc(c.city)} · ${esc(c.country)}</p><p>${esc(c.terms)} · ${esc(c.paymentTerms)}</p><div class="cta-row"><button class="btn" onclick="go('quick')">${t('quickOrder')}</button><button class="btn secondary" onclick="go('collection')">${t('collection')}</button></div></div><div class="portal-card"><h3>${owT('orders')}</h3>${owOrderTable(os)}</div><div class="portal-card"><h3>${owT('wishlist')}</h3><div class="products">${wl.map(owProductCard).join('')||`<p>${owT('noData')}</p>`}</div></div><div class="portal-card"><h3>${owT('requests')}</h3>${owRequestCards(false)}</div><div class="portal-card"><h3>${owT('sets')}</h3><p class="micro">${owT('setHint')}</p>${state.orderDesk.sets.filter(s=>s.active).map(owSetCard).join('')}</div><p class="micro">${owT('demo')}</p>`}
function owRenderOrders(){const os=owVisibleOrders();if(!os.some(o=>o.id===state.selectedOrder))state.selectedOrder=os[0]?.id;document.getElementById('ordersList').innerHTML=os.map(o=>`<div class="order-item ${state.selectedOrder===o.id?'active':''}"><button class="ow-order-btn" onclick="state.selectedOrder='${o.id}';renderOrders()"><strong>${esc(o.id)}</strong><span>${owStatus(o.status)}</span><small>${esc(o.client)} · ${orderUnits(o)} · ${money(orderValue(o))}</small></button></div>`).join('')||`<div class="empty">${owT('noData')}</div>`;const o=os.find(o=>o.id===state.selectedOrder);document.getElementById('orderDetail').innerHTML=o?owOrderHtml(o):`<div class="empty">${owT('noData')}</div>`}
function owRepeat(){const o=owVisibleOrders().find(o=>o.status==='confirmed');if(!o||state.role==='brand')return;state.draft={};state.customDraft=[];for(const l of o.lines){if(l.requestId)continue;const p=state.products.find(p=>p.id===l.productId&&p.active);if(!p||!p.sizes.includes(l.size)||!p.colors.some(c=>c[0]===l.color))continue;state.draft[l.productId]??={};state.draft[l.productId][l.color]??={};state.draft[l.productId][l.color][l.size]=l.qty}state.draftMeta={client:owClient().name,delivery:'',notes:'Repeat '+o.id};delete state.draftOrderId;save();go('quick')}
function owProfile(){const c=owClient();modal(owFormHead(owT('client'))+owClientSelect('profile')+`<p>${esc(c.name)}<br>${esc(c.contactName)}<br>${esc(c.city)} · ${esc(c.country)}<br>${esc(c.email)}</p><p>${esc(c.terms)}<br>${esc(c.paymentTerms)}</p><p class="micro">${owT('demo')}</p>`)}
function owOpenRole(){modal(owFormHead(t('role'))+owClientSelect('role')+`<div class="cta-row"><button class="btn" onclick="closeOverlay();setRole(owClient().kind==='company'?'buyer':'private');go('portal')">${owT('client')}</button><button class="btn secondary" onclick="closeOverlay();setRole('brand');go('admin')">${owT('admin')}</button></div><p class="micro">${owT('demo')}</p>`)}
function owCheckout(){if(!state.cart.length)return;state.draft={};state.customDraft=[];for(const l of state.cart){state.draft[l.productId]??={};state.draft[l.productId][l.color]??={};state.draft[l.productId][l.color][l.size]=l.qty}delete state.draftOrderId;closeOverlay();go('quick')}
/* Integrate with the original editorial shell. */
owInit();
for(const [lang,k] of Object.entries({ru:0,en:1,it:2})){Object.assign(I18N[lang],{admin:OW_WORDS.admin[k],adminIntro:OW_WORDS.demo[k],portalIntro:OW_WORDS.snapshot[k],quickIntro:OW_WORDS.setHint[k],salesCockpit:OW_WORDS.dashboard[k],smartReorder:OW_WORDS.sets[k],demoNotice:OW_WORDS.demo[k]})}
const owOldGo=go,owOldHeader=renderHeader,owOldQuick=renderQuick;
go=function(p){owOldGo(p);renderHeader()};
renderHeader=function(){owOldHeader();document.getElementById('roleChip').onclick=owOpenRole};
renderAdmin=owAdmin;renderPortal=owPortal;renderOrders=owRenderOrders;openRole=owOpenRole;
openProduct=owProduct;productCard=owProductCard;quickProduct=owQuickProduct;quickGrid=owGrid;renderSummary=owSummary;
accountB2B=p=>owPrice(p);recordIntent=owLog;toggleFavorite=owWishlist;openBuyerProfile=owProfile;
saveDraftOrder=owSaveDraft;submitWholesale=owSubmit;quickLines=owDraftLines;
quickTotals=function(){const ls=owDraftLines();return{units:ls.reduce((a,l)=>a+l.qty,0),value:owRound(ls.reduce((a,l)=>a+l.qty*l.unit,0))}};
orderValue=o=>owRound(o.lines.reduce((a,l)=>a+owRound(l.qty*l.unit*(1-(o.discount||0)/100)),0));
productDraftTotalLabel=pid=>{const ls=owDraftLines().filter(l=>l.productId===pid);return ls.reduce((n,l)=>n+l.qty,0)+' '+owT('units')+' · '+money(ls.reduce((n,l)=>n+l.qty*l.unit,0))};
money=v=>new Intl.NumberFormat(state.lang==='it'?'it-IT':state.lang==='ru'?'ru-RU':'en-GB',{style:'currency',currency:'EUR',minimumFractionDigits:0,maximumFractionDigits:2}).format(v||0);
openProductForm=owProductForm;saveProductForm=owProductSaveUI;openCollectionForm=owCollectionForm;saveCollectionForm=owCollectionSaveUI;
duplicateProduct=id=>owProductForm(id,true);
renderQuick=function(){owOldQuick();if(state.customDraft.length)document.getElementById('quickList').insertAdjacentHTML('afterbegin',`<div class="order-product"><h3>${owT('requests')}</h3>${state.customDraft.map(l=>`<div class="line-row"><div>${esc(l.article)} · ${esc(l.color)} · ${esc(l.size)}<br>${esc(l.composition)}<p>${l.qty} × ${money(l.unit)} · ${esc(l.deliveryDate)}</p></div><button class="btn small secondary" onclick="owRemoveCustom('${l.requestId}')">${owT('remove')}</button></div>`).join('')}</div>`);const b=document.getElementById('quickFilters').querySelector('button[onclick="applySuggestedReorder()"]');if(b){b.textContent=owT('sets');b.setAttribute('onclick',"go('portal')")}};
setRole=function(r){state.role=r;save();renderAll()};
openCheckout=owCheckout;submitCheckout=owCheckout;cartTotal=()=>state.cart.reduce((n,l)=>n+l.qty*owPrice(state.products.find(p=>p.id===l.productId)),0);
repeatPrevious=owRepeat;applySuggestedReorder=()=>go('portal');
orderDetailHtml=o=>owOrderHtml(o);approveOrderCycle=owOffer;setStatus=function(id,s){if(s==='confirmed')return owOffer(id);if(s==='cancelled')return owCancel(id);return false};
renderPrivate=function(){const c=owClient();document.getElementById('privateForm').innerHTML=`<h2>${owT('person')}</h2>${owClientSelect('private')}<p>${esc(c.name)} · ${esc(c.city)} · ${esc(c.country)}</p><p>${esc(c.terms)}</p><div class="cta-row"><button class="btn" onclick="go('collection')">${t('collection')}</button><button class="btn secondary" onclick="go('portal')">${owT('requests')}</button></div>`};
const owOldSend=sendMessage,owOldNote=addInternal;
sendMessage=function(id){if(owVisibleOrders().some(o=>o.id===id))owOldSend(id)};
addInternal=function(id){if(state.role==='brand')owOldNote(id)};
resetDemo=function(){if(!confirm('Reset local demo records?'))return;const lang=state.lang;state=defaultState();state.lang=lang;state.assortment=['p1','p2','p4','p5','p7','p9'];initCommercialState();owInit();save();renderAll();go('home')};

openMobileSummary=function(){const html=document.getElementById('orderSummary').innerHTML.replaceAll('owClient-quick','owClient-modal').replaceAll('draftDelivery','draftDelivery-modal').replaceAll('draftNotes','draftNotes-modal').replace('owActivate(this.value)','closeOverlay();owActivate(this.value);openMobileSummary()');modal('<div class="modal-head"><h2>'+t('orderSummary')+'</h2><button class="x" onclick="closeOverlay()">×</button></div><div class="summary ow-modal-summary">'+html+'</div>')};
openSavedSelection=function(){const ps=state.products.filter(p=>p.active&&isFav(p.id));modal(owFormHead(owT('wishlist'))+'<div class="products">'+ps.map(owProductCard).join('')+'</div>','wide')};
shareSavedSelection=function(){const ps=state.products.filter(p=>p.active&&isFav(p.id));owDownload('Marco-Pescarolo-wishlist.csv', [['Client',owClient().name],['Article','Product','Season','Unit EUR'],...ps.map(p=>[p.article,p.name,p.season,owPrice(p)])])};
